using System;using System.IO;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace CircuitoStudio {
 public sealed class DrawingDxfForm:Form {
  readonly Project project;readonly Board board;readonly Panel canvas=new Panel{Dock=DockStyle.Fill,BackColor=Color.White};readonly TextBox info=new TextBox{Dock=DockStyle.Bottom,Height=130,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};DxfInspection inspected;AmbInspection amb;public string PreviewError{get;private set;}
  public DrawingDxfForm(Project p,Board b){if(p==null||b==null||!p.Boards.Contains(b))throw new InvalidDataException("Selecione um quadro do projeto.");project=p;board=b;Text="Intercâmbio de desenho AMB / DXF — "+b.Id;Size=new Size(1250,850);MinimumSize=new Size(900,650);Font=new Font("Segoe UI",10);var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=85};Add(tools,"Exportar unifilar DXF",()=>Export(false));Add(tools,"Exportar frontal DXF",()=>Export(true));Add(tools,"Inspecionar DXF externo",()=>{using(var dialog=new OpenFileDialog{Filter="Desenho DXF|*.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK)LoadDrawing(dialog.FileName);});Add(tools,"Inspecionar AMB externo",()=>{using(var dialog=new OpenFileDialog{Filter="Desenho AMB|*.amb;*.e-design"})if(dialog.ShowDialog(this)==DialogResult.OK)LoadAmb(dialog.FileName);});Add(tools,"Reexportar original sem alterações",()=>{if(inspected==null)throw new InvalidDataException("Abra um DXF para inspecionar.");using(var dialog=new SaveFileDialog{Filter=amb==null?"Desenho DXF|*.dxf":"Desenho AMB|*.amb",FileName=amb==null?"Desenho-preservado.dxf":"Desenho-preservado.amb"})if(dialog.ShowDialog(this)==DialogResult.OK){if(amb!=null)amb.SaveOriginal(dialog.FileName);else inspected.SaveOriginal(dialog.FileName);}});canvas.Paint+=(sender,args)=>{try{Draw(sender,args);}catch(Exception ex){PreviewError=ex.ToString();info.Text="Prévia indisponível: "+ex.Message;}};canvas.Resize+=(s,e)=>canvas.Invalidate();Controls.Add(canvas);Controls.Add(info);Controls.Add(tools);info.Text=DrawingDxf.Scope+"\r\nExporta o quadro selecionado. Importação é inspeção isolada e reexportação dos bytes originais, sem incorporar desenho ao projeto. R12 sem unidade automática: frontal usa mm, unifilar usa unidades abstratas. AMB: inspeção estrutural e prévia limitada; reexportação integral dos bytes, sem edição de desenho ou circuito.";}
  void Add(Control parent,string title,Action action){var button=new Button{Text=title,AutoSize=true};button.Click+=(s,e)=>{try{action();}catch(Exception ex){info.Text="Operação recusada: "+ex.Message;}};parent.Controls.Add(button);}
  void Export(bool frontal){using(var dialog=new SaveFileDialog{Filter="Desenho DXF R12|*.dxf",FileName=frontal?"Frontal.dxf":"Unifilar.dxf"})if(dialog.ShowDialog(this)==DialogResult.OK){DrawingDxf.Save(frontal?DrawingDxf.Frontal(project,board):DrawingDxf.Unifilar(project,board),dialog.FileName);LoadDrawing(dialog.FileName);}}
  public void LoadDrawing(string path){var parsed=DrawingDxf.Inspect(path);amb=null;PreviewError=null;inspected=parsed;info.Text=parsed.Summary;info.SelectionStart=0;info.SelectionLength=0;canvas.Invalidate();}
  public void LoadAmb(string path){var parsed=DrawingAmb.Inspect(path);amb=parsed;inspected=parsed.Drawing;PreviewError=null;info.Text=parsed.Summary;info.SelectionStart=0;info.SelectionLength=0;canvas.Invalidate();}
  void Draw(object sender,PaintEventArgs args){if(inspected==null||inspected.Entities.Count==0)return;var entities=inspected.Entities;double minX=Double.MaxValue,minY=Double.MaxValue,maxX=Double.MinValue,maxY=Double.MinValue;Action<double,double> point=(x,y)=>{minX=Math.Min(minX,x);minY=Math.Min(minY,y);maxX=Math.Max(maxX,x);maxY=Math.Max(maxY,y);};foreach(var e in entities){point(e.X,e.Y);if(e.Type=="LINE")point(e.X2,e.Y2);if(e.Type=="CIRCLE"){point(e.X-e.Radius,e.Y-e.Radius);point(e.X+e.Radius,e.Y+e.Radius);}if(e.Type=="TEXT"){point(e.X+Math.Min(255,e.Text.Length)*e.Height*.7,e.Y+e.Height);}}
   double scale=Math.Min(Math.Max(1,canvas.ClientSize.Width-50)/Math.Max(1,maxX-minX),Math.Max(1,canvas.ClientSize.Height-50)/Math.Max(1,maxY-minY));var g=args.Graphics;Func<double,float> sx=x=>(float)(25+(x-minX)*scale);Func<double,float> sy=y=>(float)(25+(maxY-y)*scale);foreach(var e in entities){if(e.Type=="LINE")g.DrawLine(Pens.DarkSlateGray,sx(e.X),sy(e.Y),sx(e.X2),sy(e.Y2));if(e.Type=="CIRCLE")g.DrawEllipse(Pens.DarkSlateGray,sx(e.X-e.Radius),sy(e.Y+e.Radius),(float)(2*e.Radius*scale),(float)(2*e.Radius*scale));if(e.Type=="TEXT"){var state=g.Save();g.TranslateTransform(sx(e.X),sy(e.Y));g.RotateTransform((float)-e.Rotation);using(var font=new Font(Font.FontFamily,(float)Math.Max(2,Math.Min(100,e.Height*scale)),FontStyle.Regular,GraphicsUnit.Pixel))g.DrawString(e.Text,font,Brushes.Black,0,(float)(-e.Height*scale));g.Restore(state);}}
  }
 }
 partial class Studio {void OpenDxfInterchange(){using(var form=new DrawingDxfForm(project,board))form.ShowDialog(this);}}
}
